import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { resolvePrintActor } from "@/lib/print-access";
import { makeGetInformeGrupo } from "@/modules/consultas/infrastructure/container";
import { makeGetMyInstitution } from "@/modules/institutions/infrastructure/container";
import { readLogoIfNeeded } from "@/shared/infrastructure/storage/logo";
import "./informe-grupo-pdf.css";

export const metadata: Metadata = { title: "Informe detallado por grupo" };

/**
 * Render server-side del Informe detallado por grupo en PDF (kind =
 * "informe-grupo"). El worker de Puppeteer abre esta página con un token
 * firmado (HMAC) y la convierte a PDF (A4 portrait, una página por
 * estudiante). El documento no tiene estado interactivo — solo se imprime.
 *
 * El HTML/CSS replica exactamente la plantilla institucional
 * `tmp/prueba_2026_2.html`: misma jerarquía (`.page` → `.header` con
 * patrón SVG azul + 2 logos + título; `.pdt` con banner de institución,
 * meta-grid 2×2, etiqueta de estudiante, tabla 7-col con rayas zebra,
 * mensaje serif itálica, footer 3-col). Las clases son las mismas para que
 * el CSS sea un port 1:1.
 *
 * El token se firma con {periodId, groupId, institutionId, kind} y la
 * página valida que coincidan antes de cargar datos. Sin token válido (o
 * sin sesión autenticada para previsualización manual), caemos al
 * `requireAuthenticatedUser()` que redirige a /login.
 */
export default async function PrintInformeGrupoPage({
  params,
  searchParams,
}: {
  params: Promise<{ periodId: string; groupId: string }>;
  searchParams: Promise<{ t?: string }>;
}) {
  const { periodId, groupId } = await params;
  const { t } = await searchParams;
  const actor = await resolvePrintActor(t, {
    periodId,
    groupId,
    kind: "informe-grupo",
  });

  const [informeRes, instRes] = await Promise.all([
    makeGetInformeGrupo().execute({ actor, periodId, groupId }),
    makeGetMyInstitution().execute({ actor }),
  ]);
  if (!informeRes.ok) notFound();
  const { informe } = informeRes.value;
  if (!informe) notFound();
  const institution = instRes.ok ? instRes.value : null;

  // `theme.showLogo` lo controla el admin institucional — si no hay theme
  // cargado o está malformado, mostramos el logo por defecto (true). El
  // cover-designer y el editor de cuadernillos siguen la misma convención.
  const showLogo =
    !institution ||
    (typeof institution.theme === "object" &&
    institution.theme !== null &&
    "showLogo" in institution.theme
      ? Boolean((institution.theme as { showLogo?: unknown }).showLogo)
      : true);
  // El template tiene dos slots de logo (`.logo-ecu` municipio +
  // `.logo-school` colegio, con un divisor vertical). El modelo solo trae
  // un logo institucional, así que lo colocamos en el slot del colegio y
  // dejamos el del municipio vacío — `.logos` es flex con gap, no se
  // distorsiona si falta uno.
  const logoSrc = await readLogoIfNeeded(institution?.logo ?? null, showLogo);

  const today = new Date().toLocaleDateString("es-CO", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });

  return (
    <main>
      {informe.filas.map((fila) => (
        <section className="page" key={fila.studentId}>
          <header className="header">
            <div className="instructions-pattern patternAzul" aria-hidden="true" />
            <div className="logos">
              <div className="divider" />
              <img
                src="data:image/png;base64,"
                alt="Logo ECU"
              />

              {logoSrc ? <img src="data:image/png;base64," alt="Logo institucional"/> : null}
            </div>
            <div className="title">
              <div className="main">PRUEBA</div>
              <div className="year">{informe.prueba.year}</div>
            </div>
          </header>

          <div className="pdt">
            <div className="institution">{institution?.name ?? "Institución educativa"}</div>

            <section className="meta">
              <div className="meta-row">
                <span>12/09/2026</span>
                <span>Examen Final II Periodo</span>
              </div>
              <div className="meta-row">
                <span>Grado: {informe.grupo.name}</span>
                <span>Id: {fila.codigo}</span>
              </div>
            </section>

            <div className="student">Estudiante: {fila.nombre}</div>

            <section className="report">
              <table>
                <thead>
                  <tr>
                    <th />
                    <th>Calificación</th>
                    <th>
                      Respuestas
                      <br />
                      Correctas
                    </th>
                    <th>
                      Respuestas
                      <br />
                      Incorrectas
                    </th>
                    <th>
                      Sin
                      <br />
                      Seleccionar
                    </th>
                    <th>
                      Calificación
                      <br />
                      total
                    </th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {informe.asignaturas.map((a) => {
                    const p = fila.puntajes[a.subjectId];
                    return (
                      <tr key={a.subjectId}>
                        <td className="subject">{a.nombre}</td>
                        <td>{p ? fmtPuntaje(p.puntaje) : "—"}</td>
                        <td>{p ? p.correctas : "—"}</td>
                        <td>{p ? p.incorrectas : "—"}</td>
                        <td>{p ? p.enBlanco : "—"}</td>
                        <td>{p ? `${p.correctas} / ${p.total}` : "—"}</td>
                        <td className="bar-cell">
                          {p ? (
                            <span className="bar">
                              <span
                                className="fill"
                                style={{
                                  width: `${Math.max(0, Math.min(100, (p.puntaje / 10) * 100))}%`,
                                }}
                              />
                            </span>
                          ) : (
                            "—"
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </section>

            <div className="message">
              <div>Valoramos tus aportes que hacen real este proyecto institucional.</div>
              <strong>Excelencia educativa, un trabajo de todos!!!</strong>
            </div>

            <footer className="footer">
              <div>{today}</div>
              <div>{institution?.name ?? ""}</div>
              {/* Columna derecha vacía — el worker estampa aquí "Página X de Y"
                  con pdf-lib (Chromium no exporta counter(pages) en headless). */}
              <div />
            </footer>
          </div>
        </section>
      ))}
    </main>
  );
}

/** Formato colombiano: "4,0" en vez de "4.0" — coincide con la plantilla. */
function fmtPuntaje(n: number): string {
  return n.toFixed(1).replace(".", ",");
}
